mapper.select:
SELECT g.id, g.gateway_code AS gatewayCode, g.gateway_name AS gatewayName, g.ip_address AS ipAddress, g.port, g.protocol, g.online_status AS onlineStatus, CASE g.online_status WHEN 1 THEN '在线' ELSE '离线' END AS onlineStatusText, g.last_online_time AS lastOnlineTime, g.status, CASE g.status WHEN 1 THEN '正常' ELSE '禁用' END AS statusText, g.create_by AS createBy, g.create_time AS createTime FROM agri_iot_gateway g WHERE g.del_flag = 0
AND g.gateway_code LIKE CONCAT('%', #{dto.gatewayCode}, '%')
AND g.gateway_name LIKE CONCAT('%', #{dto.gatewayName}, '%')
AND g.online_status = #{dto.onlineStatus}
AND g.status = #{dto.status}
ORDER BY g.create_time DESC LIMIT #{dto.pageNum}, #{dto.pageSize}

SELECT COUNT(*) FROM agri_iot_gateway g WHERE g.del_flag = 0
AND g.gateway_code LIKE CONCAT('%', #{dto.gatewayCode}, '%')
AND g.gateway_name LIKE CONCAT('%', #{dto.gatewayName}, '%')
AND g.online_status = #{dto.onlineStatus}
AND g.status = #{dto.status}
